#!/usr/bin/env python3
"""Parameterized test bot. argv[1]=mode, argv[2]=payload"""
import sys, time
mode = sys.argv[1]; payload = sys.argv[2] if len(sys.argv)>2 else ''
def rl(): return sys.stdin.readline()
if mode == 'crash_init':
    sys.exit(1)
if mode == 'no_name_sleep':
    # read init, never send name, sleep long
    for _ in range(4): rl()
    time.sleep(float(payload or 20))
    sys.exit(0)
if mode == 'name_then_crash':
    for _ in range(4): rl()
    print('Crasher'); sys.stdout.flush()
    n = int(payload or 3)
    for i in range(n):
        rl(); print(''); sys.stdout.flush()
    sys.exit(2)
if mode == 'name_then_eof':
    for _ in range(4): rl()
    print('Eofer'); sys.stdout.flush()
    n = int(payload or 3)
    for i in range(n):
        rl(); print(''); sys.stdout.flush()
    sys.stdout.close(); sys.stderr.close()
    try:
        sys.exit(0)
    except SystemExit: raise
if mode == 'empty_name':
    for _ in range(4): rl()
    print(''); sys.stdout.flush()
    while rl(): print(''); sys.stdout.flush()
if mode == 'custom_name':
    for _ in range(4): rl()
    print(payload); sys.stdout.flush()
    while rl(): print(''); sys.stdout.flush()
if mode == 'garbage':
    # send name, then garbage move lines per payload file
    for _ in range(4): rl()
    print('GarbageBot'); sys.stdout.flush()
    lines = open(payload).read().split('\n')
    i = 0
    while True:
        f = rl()
        if not f: break
        print(lines[i] if i < len(lines) else ''); sys.stdout.flush()
        i += 1
if mode == 'partial_then_eof':
    for _ in range(4): rl()
    print('Partial'); sys.stdout.flush()
    rl()
    sys.stdout.write(payload)  # no newline
    sys.stdout.flush()
    sys.exit(0)
if mode == 'slow_frame':
    for _ in range(4): rl()
    print('SlowBot'); sys.stdout.flush()
    while True:
        f = rl()
        if not f: break
        time.sleep(float(payload or 3))
        print(''); sys.stdout.flush()
if mode == 'partial_then_sleep':
    for _ in range(4): rl()
    print('PartialSleeper'); sys.stdout.flush()
    rl()
    sys.stdout.write(payload); sys.stdout.flush()
    time.sleep(30)
EOF
